SELECT percentile_cont(0.25) within GROUP (ORDER BY icustays.los) AS percentile_25 FROM admissions JOIN patients ON admissions.subject_id = patients.subject_id JOIN icustays ON admissions.stay_id = icustays.stay_id WHERE patients.gender = 'M' AND patients.anchor_age = 48 AND patients.anchor_year = 2017 AND patients.anchor_year_group BETWEEN 43 AND 53 AND icustays.first_careunit = 'ICU';